cat > tests/deliver_test.sh <<'E'
#!/bin/bash
# deliver: a succeeding command is delivered on the first attempt; a failing one exits 1.
fail=0
[ "$(RELAY_SLEEP=: bash bin/deliver true | tail -1)" = delivered ] || { echo "deliver true"; fail=1; }
RELAY_SLEEP=: bash bin/deliver false >/dev/null; [ $? = 1 ] || { echo "deliver false"; fail=1; }
# ADR-0009: 4 attempts, waits 3^i (3, 9, 27 s); count set by RELAY_ATTEMPTS (docs/runbook.md)
[ "$(bash bin/deliver --plan)" = "attempts=4 waits=3,9,27" ] || { echo "plan default"; fail=1; }
[ "$(RELAY_ATTEMPTS=6 bash bin/deliver --plan)" = "attempts=6 waits=3,9,27,81,243" ] || { echo "plan RELAY_ATTEMPTS"; fail=1; }
exit $fail
E
bash tests/deliver_test.sh; echo exit $?

cd /app; 
cat > lib/delivery/retry.sh <<'E'
#!/bin/bash
# Retry schedule for webhook delivery (docs/adr/0009-webhook-retry-policy.md).
# Attempts: RELAY_ATTEMPTS (default 4). Wait before attempt i+1: 3^i seconds (3, 9, 27).
RELAY_ATTEMPTS_DEFAULT=4
RELAY_WAIT_BASE=3
RELAY_WAIT_FIRST=3
relay_attempts() { echo "${RELAY_ATTEMPTS:-$RELAY_ATTEMPTS_DEFAULT}"; }
relay_wait_for() { local i="$1" w="$RELAY_WAIT_FIRST"; while [ "$i" -gt 1 ]; do w=$(( w * RELAY_WAIT_BASE )); i=$(( i - 1 )); done; echo "$w"; }
relay_waits() { local n i=1 out=""; n=$(relay_attempts); while [ "$i" -lt "$n" ]; do out="${out:+$out,}$(relay_wait_for "$i")"; i=$(( i + 1 )); done; echo "$out"; }
E
sed -i 's/^3 attempts with doubling waits.*/4 attempts with waits of 3, 9, 27 s (ADR-0009, which supersedes the original draft of 3 attempts with doubling waits). The count can be raised with RELAY_ATTEMPTS for a slow partner./' docs/design/delivery.md
sed -i '0,/^## 3.4.1/s//## Unreleased\n\n- deliver: restore the ADR-0009 retry policy (4 attempts, waits 3 s, 9 s, 27 s) and read the count from `RELAY_ATTEMPTS` again; `RELAY_RETRY_MAX` is not read (RLY-731)\n\n## 3.4.1/' CHANGELOG.md
scripts/verify.sh; bash bin/deliver --plan; RELAY_ATTEMPTS=6 bash bin/deliver --plan; git diff --stat
grep -rn "RELAY_RETRY_MAX\|doubling" docs lib bin | grep -v CHANGELOG
